command:
if (!game.user.isGM) {
  ui.notifications.warn("Apenas o mestre pode resetar os handouts revelados.");
  return;
}

const NOMES_JOURNAL_MUNDO = {
  "Ato I": "Handouts Revelados — Ato I",
  "Ato II": "Handouts Revelados — Ato II"
};

const comConteudo = Object.entries(NOMES_JOURNAL_MUNDO)
  .map(([ato, nome]) => ({ ato, nome, journal: game.journal.getName(nome) }))
  .filter((e) => e.journal && e.journal.pages.size);

if (!comConteudo.length) {
  ui.notifications.info("Não há nenhum handout revelado pra resetar.");
  return;
}

const opcoes = comConteudo.map((e) => `<option value="${e.ato}">${e.ato} (${e.journal.pages.size} handout(s))</option>`).join("");
const escolha = await foundry.applications.api.DialogV2.input({
  window: { title: "Resetar Handouts Revelados" },
  content: `<div class="form-group"><label>Qual Ato você quer resetar?</label><select name="ato" style="width:100%">${opcoes}${comConteudo.length > 1 ? '<option value="Ambos">Ambos os Atos</option>' : ""}</select></div>`,
  ok: { label: "Continuar" }
});
if (!escolha) return;

const alvos = escolha.ato === "Ambos" ? comConteudo : comConteudo.filter((e) => e.ato === escolha.ato);
const totalPaginas = alvos.reduce((soma, e) => soma + e.journal.pages.size, 0);
const listaAtos = alvos.map((e) => e.ato).join(" e ");

const confirmado = await foundry.applications.api.DialogV2.confirm({
  window: { title: "Resetar Handouts Revelados" },
  content: `<p>Isso vai apagar os <strong>${totalPaginas}</strong> handout(s) já revelados aos jogadores do ${listaAtos}. Não dá pra desfazer.</p><p>Na próxima vez que você usar "Revelar Handout", todos vão aparecer como disponíveis de novo, como se nada tivesse sido mostrado ainda.</p>`,
  rejectClose: false
});
if (!confirmado) return;

for (const alvo of alvos) {
  const idsPaginas = alvo.journal.pages.map((p) => p.id);
  await alvo.journal.deleteEmbeddedDocuments("JournalEntryPage", idsPaginas);
}

ui.notifications.info(`Handouts revelados resetados (${listaAtos})! Todos voltaram a ficar disponíveis pra revelar de novo.`);
